import './styles.css';
import { useState } from 'react';

interface Question {
  id: string;
  category: string;
  question: string;
  description: string;
  considerations: string[];
  riskLevel: 'high' | 'medium' | 'low';
}

interface Answer {
  response: 'yes' | 'no' | 'unsure' | null;
  notes: string;
}

const questions: Question[] = [
  {
    id: 'harm',
    category: 'Potential Harm',
    question: 'Have you identified who might be harmed or excluded by this AI solution?',
    description: 'Consider direct users, people affected by AI decisions, and communities represented in outputs.',
    considerations: [
      'Could the AI make biased decisions about people?',
      'Are there groups who might be disadvantaged by AI errors?',
      'Could AI outputs spread misinformation that harms communities?',
      'Are vulnerable populations involved?',
    ],
    riskLevel: 'high',
  },
  {
    id: 'transparency',
    category: 'Transparency',
    question: 'Do you have a plan for transparency about AI use with stakeholders?',
    description: 'Consider what disclosure you owe to funders, partners, beneficiaries, and the public.',
    considerations: [
      'Will you disclose when content is AI-generated?',
      'How will you communicate AI use to funders/donors?',
      'Are there regulatory requirements for AI disclosure?',
      'What do stakeholders expect regarding AI transparency?',
    ],
    riskLevel: 'medium',
  },
  {
    id: 'human-agency',
    category: 'Human Oversight',
    question: 'Will meaningful human oversight be maintained over AI outputs and decisions?',
    description: 'Ensure humans remain in control of important decisions and can override AI recommendations.',
    considerations: [
      'Who will review AI outputs before they are used?',
      'Are there decisions that should NEVER be automated?',
      'Can humans easily override AI recommendations?',
      'Is there a clear escalation path for AI errors?',
    ],
    riskLevel: 'high',
  },
  {
    id: 'accuracy',
    category: 'Verification',
    question: 'Do you have processes to verify AI outputs and ensure accuracy?',
    description: 'AI can confidently produce incorrect information. Verification processes are essential.',
    considerations: [
      'How will factual claims be verified?',
      'Who is qualified to review AI outputs in this domain?',
      'What are the consequences if AI provides wrong information?',
      'Do you have fact-checking procedures in place?',
    ],
    riskLevel: 'high',
  },
  {
    id: 'bias',
    category: 'Bias & Fairness',
    question: 'Have you assessed how AI bias might affect your work?',
    description: 'AI can reflect and amplify societal biases present in training data.',
    considerations: [
      'Could AI outputs contain stereotypes or unfair representations?',
      'Are certain languages, cultures, or groups underrepresented?',
      'How will you monitor for bias in AI outputs?',
      'Do you have diverse perspectives reviewing AI use?',
    ],
    riskLevel: 'medium',
  },
  {
    id: 'data-privacy',
    category: 'Data Privacy',
    question: 'Have you considered data privacy implications of AI use?',
    description: 'Data entered into AI systems may be stored, used for training, or accessed by providers.',
    considerations: [
      'Will sensitive or personal data be shared with AI systems?',
      'Do you understand the AI provider\'s data policies?',
      'Are there legal requirements for data protection?',
      'Have affected individuals consented to AI processing?',
    ],
    riskLevel: 'high',
  },
  {
    id: 'appropriate-use',
    category: 'Appropriate Use',
    question: 'Is AI the right tool for this task?',
    description: 'Just because AI CAN do something doesn\'t mean it SHOULD.',
    considerations: [
      'Could this task be done better or more safely without AI?',
      'Is the task appropriate for AI\'s current capabilities?',
      'Are there regulatory or ethical boundaries being pushed?',
      'Does AI use align with your organization\'s values?',
    ],
    riskLevel: 'medium',
  },
  {
    id: 'feedback',
    category: 'Feedback Mechanisms',
    question: 'Do you have ways for people to report problems with AI use?',
    description: 'Create channels for identifying and addressing AI errors or harmful outputs.',
    considerations: [
      'Can users easily report AI errors or concerns?',
      'Who is responsible for responding to AI-related complaints?',
      'How will you track and learn from AI problems?',
      'Is there a process for making corrections?',
    ],
    riskLevel: 'low',
  },
];

const categoryColors: Record<string, string> = {
  'Potential Harm': '#ef4444',
  'Transparency': '#3b82f6',
  'Human Oversight': '#f59e0b',
  'Verification': '#10b981',
  'Bias & Fairness': '#8b5cf6',
  'Data Privacy': '#ec4899',
  'Appropriate Use': '#06b6d4',
  'Feedback Mechanisms': '#84cc16',
};

function QuestionCard({
  question,
  answer,
  onAnswer,
  isExpanded,
  onToggle,
}: {
  question: Question;
  answer: Answer;
  onAnswer: (response: Answer['response'], notes: string) => void;
  isExpanded: boolean;
  onToggle: () => void;
}) {
  const color = categoryColors[question.category];
  const isAnswered = answer.response !== null;

  return (
    <div 
      className={`question-card ${isAnswered ? 'answered' : ''} ${isExpanded ? 'expanded' : ''}`}
      style={{ borderLeftColor: color }}
    >
      <div className="card-header" onClick={onToggle}>
        <div className="header-content">
          <span className="category-badge" style={{ backgroundColor: color }}>
            {question.category}
          </span>
          <h3 className="question-text">{question.question}</h3>
        </div>
        <div className="header-right">
          {isAnswered && (
            <span className={`answer-indicator ${answer.response}`}>
              {answer.response === 'yes' ? '✓' : answer.response === 'no' ? '✗' : '?'}
            </span>
          )}
          <span className="expand-icon">{isExpanded ? '−' : '+'}</span>
        </div>
      </div>

      {isExpanded && (
        <div className="card-content">
          <p className="description">{question.description}</p>

          <div className="considerations">
            <strong>Things to consider:</strong>
            <ul>
              {question.considerations.map((c, i) => (
                <li key={i}>{c}</li>
              ))}
            </ul>
          </div>

          <div className="response-section">
            <strong>Your assessment:</strong>
            <div className="response-buttons">
              <button
                className={`response-btn yes ${answer.response === 'yes' ? 'selected' : ''}`}
                onClick={() => onAnswer('yes', answer.notes)}
              >
                Yes, addressed
              </button>
              <button
                className={`response-btn unsure ${answer.response === 'unsure' ? 'selected' : ''}`}
                onClick={() => onAnswer('unsure', answer.notes)}
              >
                Needs work
              </button>
              <button
                className={`response-btn no ${answer.response === 'no' ? 'selected' : ''}`}
                onClick={() => onAnswer('no', answer.notes)}
              >
                Not addressed
              </button>
            </div>

            <textarea
              placeholder="Add notes about your assessment..."
              value={answer.notes}
              onChange={(e) => onAnswer(answer.response, e.target.value)}
              className="notes-input"
            />
          </div>
        </div>
      )}
    </div>
  );
}

function Summary({ answers, questions }: { answers: Record<string, Answer>; questions: Question[] }) {
  const stats = {
    yes: 0,
    unsure: 0,
    no: 0,
    unanswered: 0,
  };

  questions.forEach(q => {
    const response = answers[q.id]?.response;
    if (response === 'yes') stats.yes++;
    else if (response === 'unsure') stats.unsure++;
    else if (response === 'no') stats.no++;
    else stats.unanswered++;
  });

  const total = questions.length;
  const addressed = stats.yes;
  const concerns = stats.no + stats.unsure;

  let overallStatus = 'ready';
  let statusMessage = 'You\'ve addressed the key ethical considerations.';
  let statusColor = '#10b981';

  if (stats.no > 0) {
    overallStatus = 'caution';
    statusMessage = 'There are unaddressed concerns that need attention before proceeding.';
    statusColor = '#ef4444';
  } else if (stats.unsure > 2) {
    overallStatus = 'review';
    statusMessage = 'Several areas need more work. Consider getting additional input.';
    statusColor = '#f59e0b';
  } else if (stats.unanswered > 0) {
    overallStatus = 'incomplete';
    statusMessage = 'Complete all questions for a full assessment.';
    statusColor = '#6b7280';
  }

  return (
    <div className="summary-panel" style={{ borderColor: statusColor }}>
      <h2>Assessment Summary</h2>

      <div className="stats-grid">
        <div className="stat addressed">
          <span className="stat-number">{stats.yes}</span>
          <span className="stat-label">Addressed</span>
        </div>
        <div className="stat needs-work">
          <span className="stat-number">{stats.unsure}</span>
          <span className="stat-label">Needs Work</span>
        </div>
        <div className="stat not-addressed">
          <span className="stat-number">{stats.no}</span>
          <span className="stat-label">Not Addressed</span>
        </div>
        <div className="stat unanswered">
          <span className="stat-number">{stats.unanswered}</span>
          <span className="stat-label">Unanswered</span>
        </div>
      </div>

      <div className="status-message" style={{ backgroundColor: statusColor + '20', borderColor: statusColor }}>
        <p style={{ color: statusColor }}>{statusMessage}</p>
      </div>

      {stats.no > 0 && (
        <div className="action-items">
          <strong>Priority action items:</strong>
          <ul>
            {questions
              .filter(q => answers[q.id]?.response === 'no')
              .map(q => (
                <li key={q.id}>{q.category}: {q.question}</li>
              ))}
          </ul>
        </div>
      )}
    </div>
  );
}

export default function App() {
  const [answers, setAnswers] = useState<Record<string, Answer>>(
    Object.fromEntries(questions.map(q => [q.id, { response: null, notes: '' }]))
  );
  const [expandedId, setExpandedId] = useState<string | null>(questions[0].id);

  const handleAnswer = (id: string, response: Answer['response'], notes: string) => {
    setAnswers(prev => ({
      ...prev,
      [id]: { response, notes }
    }));
  };

  const handleToggle = (id: string) => {
    setExpandedId(expandedId === id ? null : id);
  };

  return (
    <div className="app">
      <div className="header">
        <h1>AI Ethics Checklist</h1>
        <p className="subtitle">
          Evaluate ethical considerations before adopting AI in your organization
        </p>
      </div>

      <div className="main-content">
        <div className="questions-column">
          {questions.map(question => (
            <QuestionCard
              key={question.id}
              question={question}
              answer={answers[question.id]}
              onAnswer={(response, notes) => handleAnswer(question.id, response, notes)}
              isExpanded={expandedId === question.id}
              onToggle={() => handleToggle(question.id)}
            />
          ))}
        </div>

        <div className="summary-column">
          <Summary answers={answers} questions={questions} />
        </div>
      </div>

      <div className="insight-box">
        <h3>Using This Checklist</h3>
        <p>
          This checklist helps you think through key ethical considerations <strong>before</strong> adopting AI tools. It's not a compliance checklist - it's a thinking tool to surface concerns and ensure thoughtful AI adoption.
        </p>
        <p>
          <strong>Remember:</strong> There are no universally "right" answers. What matters is that your organization has genuinely considered these questions and made intentional choices.
        </p>
      </div>
    </div>
  );
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, sans-serif;
  background: linear-gradient(135deg, #0f766e 0%, #14b8a6 100%);
  min-height: 100vh;
  padding: 2rem 1rem;
}

.app {
  max-width: 1100px;
  margin: 0 auto;
}

.header {
  text-align: center;
  margin-bottom: 1.5rem;
}

h1 {
  color: white;
  font-size: 2rem;
  margin-bottom: 0.5rem;
}

.subtitle {
  color: rgba(255, 255, 255, 0.9);
  font-size: 1rem;
}

.main-content {
  display: grid;
  grid-template-columns: 1fr 320px;
  gap: 1.5rem;
  margin-bottom: 1.5rem;
}

@media (max-width: 900px) {
  .main-content {
    grid-template-columns: 1fr;
  }

  .summary-column {
    order: -1;
  }
}

.questions-column {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.question-card {
  background: white;
  border-radius: 0.75rem;
  border-left: 4px solid;
  overflow: hidden;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
  transition: all 0.2s;
}

.question-card.answered {
  opacity: 0.9;
}

.question-card.expanded {
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.15);
}

.card-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  padding: 1rem;
  cursor: pointer;
  gap: 1rem;
}

.card-header:hover {
  background: #f9fafb;
}

.header-content {
  flex: 1;
}

.category-badge {
  display: inline-block;
  font-size: 0.65rem;
  font-weight: 600;
  color: white;
  padding: 0.2rem 0.5rem;
  border-radius: 0.25rem;
  margin-bottom: 0.5rem;
  text-transform: uppercase;
}

.question-text {
  font-size: 0.95rem;
  color: #1f2937;
  line-height: 1.4;
}

.header-right {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.answer-indicator {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.8rem;
  font-weight: 600;
}

.answer-indicator.yes {
  background: #d1fae5;
  color: #047857;
}

.answer-indicator.unsure {
  background: #fef3c7;
  color: #b45309;
}

.answer-indicator.no {
  background: #fee2e2;
  color: #b91c1c;
}

.expand-icon {
  font-size: 1.25rem;
  color: #9ca3af;
  width: 24px;
  text-align: center;
}

.card-content {
  padding: 0 1rem 1rem;
  border-top: 1px solid #e5e7eb;
}

.description {
  color: #6b7280;
  font-size: 0.9rem;
  line-height: 1.5;
  margin: 1rem 0;
}

.considerations {
  background: #f9fafb;
  padding: 0.75rem;
  border-radius: 0.5rem;
  margin-bottom: 1rem;
}

.considerations strong {
  display: block;
  font-size: 0.8rem;
  color: #374151;
  margin-bottom: 0.5rem;
}

.considerations ul {
  list-style: none;
  padding-left: 0;
}

.considerations li {
  font-size: 0.85rem;
  color: #4b5563;
  padding-left: 1.25rem;
  position: relative;
  margin-bottom: 0.25rem;
}

.considerations li::before {
  content: '•';
  position: absolute;
  left: 0.25rem;
  color: #9ca3af;
}

.response-section {
  margin-top: 1rem;
}

.response-section strong {
  display: block;
  font-size: 0.85rem;
  color: #374151;
  margin-bottom: 0.5rem;
}

.response-buttons {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 0.75rem;
}

.response-btn {
  flex: 1;
  padding: 0.5rem;
  border: 2px solid #e5e7eb;
  border-radius: 0.5rem;
  background: white;
  font-size: 0.8rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s;
}

.response-btn.yes:hover, .response-btn.yes.selected {
  background: #d1fae5;
  border-color: #10b981;
  color: #047857;
}

.response-btn.unsure:hover, .response-btn.unsure.selected {
  background: #fef3c7;
  border-color: #f59e0b;
  color: #b45309;
}

.response-btn.no:hover, .response-btn.no.selected {
  background: #fee2e2;
  border-color: #ef4444;
  color: #b91c1c;
}

.notes-input {
  width: 100%;
  min-height: 60px;
  padding: 0.5rem;
  border: 1px solid #e5e7eb;
  border-radius: 0.5rem;
  font-size: 0.85rem;
  resize: vertical;
}

.notes-input:focus {
  outline: none;
  border-color: #14b8a6;
}

/* Summary Panel */
.summary-column {
  position: sticky;
  top: 2rem;
  height: fit-content;
}

.summary-panel {
  background: white;
  border-radius: 1rem;
  padding: 1.5rem;
  border-top: 4px solid;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.2);
}

.summary-panel h2 {
  font-size: 1.1rem;
  color: #1f2937;
  margin-bottom: 1rem;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.75rem;
  margin-bottom: 1rem;
}

.stat {
  text-align: center;
  padding: 0.75rem;
  border-radius: 0.5rem;
}

.stat.addressed { background: #d1fae5; }
.stat.needs-work { background: #fef3c7; }
.stat.not-addressed { background: #fee2e2; }
.stat.unanswered { background: #f3f4f6; }

.stat-number {
  display: block;
  font-size: 1.5rem;
  font-weight: 700;
}

.stat.addressed .stat-number { color: #047857; }
.stat.needs-work .stat-number { color: #b45309; }
.stat.not-addressed .stat-number { color: #b91c1c; }
.stat.unanswered .stat-number { color: #6b7280; }

.stat-label {
  font-size: 0.7rem;
  text-transform: uppercase;
  color: #6b7280;
}

.status-message {
  padding: 0.75rem;
  border-radius: 0.5rem;
  border: 1px solid;
  margin-bottom: 1rem;
}

.status-message p {
  font-size: 0.85rem;
  font-weight: 500;
  margin: 0;
}

.action-items {
  background: #fef2f2;
  padding: 0.75rem;
  border-radius: 0.5rem;
}

.action-items strong {
  display: block;
  font-size: 0.8rem;
  color: #b91c1c;
  margin-bottom: 0.5rem;
}

.action-items ul {
  list-style: none;
  padding-left: 0;
}

.action-items li {
  font-size: 0.8rem;
  color: #991b1b;
  padding-left: 1rem;
  position: relative;
  margin-bottom: 0.25rem;
}

.action-items li::before {
  content: '!';
  position: absolute;
  left: 0;
  font-weight: bold;
}

.insight-box {
  background: rgba(255, 255, 255, 0.95);
  border-radius: 1rem;
  padding: 1.5rem;
}

.insight-box h3 {
  color: #1f2937;
  font-size: 1rem;
  margin-bottom: 0.75rem;
}

.insight-box p {
  color: #4b5563;
  font-size: 0.9rem;
  line-height: 1.6;
  margin-bottom: 0.75rem;
}

.insight-box p:last-child {
  margin-bottom: 0;
}
